package org.viridexa.api.protection;
import org.junit.jupiter.api.Test;import org.springframework.mock.web.*;import jakarta.servlet.http.*;import java.nio.charset.StandardCharsets;import java.util.concurrent.atomic.AtomicReference;
import static org.junit.jupiter.api.Assertions.*;
class BoundaryFiltersTest {
 @Test void broadOrHostnameProxyTrustCannotBeEnabled(){assertThrows(IllegalArgumentException.class,()->new ClientIpFilter("0.0.0.0/0"));assertThrows(IllegalArgumentException.class,()->new ClientIpFilter("::/0"));assertThrows(IllegalArgumentException.class,()->new ClientIpFilter("untrusted.invalid/32"));assertDoesNotThrow(()->new ClientIpFilter("172.30.0.10/32"));}
 @Test void untrustedForwardedHeadersCannotChooseIpOrScheme()throws Exception{var q=new MockHttpServletRequest();q.setRemoteAddr("203.0.113.1");q.addHeader("X-Viridexa-Client-IP","1.2.3.4");q.addHeader("CF-Connecting-IP","1.1.1.1");q.addHeader("X-Forwarded-For","1.1.1.2");q.addHeader("X-Viridexa-Proto","https");new ClientIpFilter("172.30.0.10/32").doFilter(q,new MockHttpServletResponse(),(a,b)->{assertEquals("203.0.113.1",a.getRemoteAddr());assertFalse(a.isSecure());});}
 @Test void onlyTrustedImmediateProxyMaySupplyNormalizedVisitor()throws Exception{var q=new MockHttpServletRequest();q.setRemoteAddr("172.30.0.10");q.addHeader("X-Viridexa-Client-IP","2001:db8::1");q.addHeader("X-Viridexa-Proto","https");new ClientIpFilter("172.30.0.10/32").doFilter(q,new MockHttpServletResponse(),(a,b)->{assertEquals("2001:db8::1",a.getRemoteAddr());assertTrue(a.isSecure());});}
 @Test void hostnamesAndMalformedAddressHeadersAreNeverDnsResolved()throws Exception{assertFalse(ClientIpFilter.literal("evil.invalid"));assertFalse(ClientIpFilter.literal("127.0.0.1,1.1.1.1"));assertFalse(ClientIpFilter.literal("999.999.999.999"));assertTrue(ClientIpFilter.literal("192.0.2.4"));}
 @Test void oversizedKnownAndChunkedRequestsAreRejectedBeforeBusinessCode()throws Exception{for(boolean chunked:new boolean[]{false,true}){var q=new MockHttpServletRequest("POST","/api/v1/account/register"){public long getContentLengthLong(){return chunked?-1:super.getContentLengthLong();}};q.setContentType("application/json");q.setContent("x".repeat(32769).getBytes(StandardCharsets.UTF_8));var r=new MockHttpServletResponse();new RequestSizeFilter().doFilter(q,r,(a,b)->fail("Oversized body reached business code"));assertEquals(413,r.getStatus());}}
 @Test void excessiveQueryAndPaginationNeverReachDomainQueries()throws Exception{for(var parameter:java.util.Map.of("q","x".repeat(121),"limit","101","cursor","x".repeat(2049)).entrySet()){var q=new MockHttpServletRequest("GET","/api/v1/science/plants");q.addParameter(parameter.getKey(),parameter.getValue());var r=new MockHttpServletResponse();new QueryBoundsFilter().doFilter(q,r,(a,b)->fail());assertEquals(400,r.getStatus());}}
 @Test void unknownShortScientificCriteriaRemainAvailableToDomainRules()throws Exception{var q=new MockHttpServletRequest("GET","/api/v1/science/identify");q.addParameter("leafShape","genuinely-unmapped-value");new QueryBoundsFilter().doFilter(q,new MockHttpServletResponse(),(a,b)->assertEquals("genuinely-unmapped-value",a.getParameter("leafShape")));}
 @Test void jsonBodyIsPreservedAndMultipartIsNotAccepted()throws Exception{var q=new MockHttpServletRequest("POST","/api/v1/agent/runs");q.setContentType("application/json");q.setContent("{\"question\":\"source\"}".getBytes(StandardCharsets.UTF_8));new RequestSizeFilter().doFilter(q,new MockHttpServletResponse(),(a,b)->assertEquals("{\"question\":\"source\"}",new String(a.getInputStream().readAllBytes(),StandardCharsets.UTF_8)));q=new MockHttpServletRequest("POST","/api/v1/account/register");q.setContentType("multipart/form-data");var r=new MockHttpServletResponse();new RequestSizeFilter().doFilter(q,r,(a,b)->fail());assertEquals(415,r.getStatus());}
}
